guided.starter:
-- Orders to Germany and distinct customers
SELECT COUNT(*) AS orders
FROM orders;

guided.solution:
SELECT COUNT(*) AS orders, COUNT(DISTINCT customer_id) AS customers
FROM orders
WHERE ship_country = 'Germany';

